                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'ADMIN_PROFILE' && isAuthenticated && <CompanyProfile onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {view === 'ADMIN_SETTINGS' && isAuthenticated && <Settings onBack={() => setView('ADMIN')} userEmail={userEmail} onUpdateAiStatus={(status) => setIsAiEnabled(status)} />}
        {view === 'ADMIN_TAXONOMY' && isAuthenticated && <TaxonomyManager onBack={() => setView('ADMIN')} categories={categories} jobTypes={contractTypes} onRefresh={() => fetchData(false)} />}

        {(view === 'ADMIN_CREATE' || view === 'ADMIN_EDIT') && isAuthenticated && (
          <div className="py-20 px-6 lg:px-12">
            <JobForm initialData={editingJob || undefined} onSubmit={handleAddJob} onCancel={() => setView('ADMIN')} isAiEnabled={isAiEnabled} availableCategories={categories} availableTypes={contractTypes} />
