import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Job, Application, ViewState } from '../types';
import { Icons } from '../constants';
import { StatsGrid } from './StatsGrid';

interface AdminModuleProps {
  jobs: Job[];
  applications: Application[];
  onLogout: () => void;
  onCreateJob: () => void;
  onViewApplications: () => void;
  onEditJob: (job: Job) => void;
  onRemoveJob: (id: string) => void;
  onNavigate: (view: ViewState) => void;
  onRefresh: () => void;
  isRefreshing?: boolean;
  stats: any;
  userEmail?: string;
}

type TimeScale = 'Daily' | 'Weekly' | 'Monthly' | 'Custom';

export const AdminModule: React.FC<AdminModuleProps> = ({
  jobs,
  applications,
  onLogout,
  onCreateJob,
  onViewApplications,
  onEditJob,
  onRemoveJob,
  onNavigate,
  onRefresh,
  isRefreshing,
  stats,
  userEmail
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [timeScale, setTimeScale] = useState<TimeScale>('Monthly');
  const [customRange, setCustomRange] = useState({ start: '', end: '' });
  const menuRef = useRef<HTMLDivElement>(null);

  const initials = userEmail ? userEmail.substring(0, 2).toUpperCase() : 'AD';

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const chartData = useMemo(() => {
    const now = new Date();
    let periods: { label: string; count: number }[] = [];
    if (timeScale === 'Daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(now.getDate() - i);
        const label = d.toLocaleDateString('it-IT', { weekday: 'short' });
        const count = applications.filter(app => new Date(app.appliedAt).toDateString() === d.toDateString()).length;
        periods.push({ label, count });
      }
    } else if (timeScale === 'Monthly') {
      for (let i = 5; i >= 0; i--) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const label = d.toLocaleDateString('it-IT', { month: 'short' }).toUpperCase();
        const count = applications.filter(app => {
          const appDate = new Date(app.appliedAt);
          return appDate.getMonth() === d.getMonth() && appDate.getFullYear() === d.getFullYear();
        }).length;
        periods.push({ label, count });
      }
    } else {
      periods = Array(6).fill(0).map((_, i) => ({ label: `T${i+1}`, count: 0 }));
    }
    const maxCount = Math.max(...periods.map(p => p.count), 1);
    return periods.map(p => ({ ...p, percentage: (p.count / maxCount) * 100 }));
  }, [applications, timeScale]);

  return (
    <div className="w-full px-6 lg:px-12 py-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
        <div>
          <h1 className="text-3xl lg:text-4xl font-bold text-slate-900 tracking-tight">Dashboard Amministratore</h1>
          <p className="text-slate-500 mt-1">Gestisci le tue posizioni aperte e monitora le performance.</p>
        </div>

        <div className="flex items-center gap-4">
          <button onClick={onRefresh} disabled={isRefreshing} className="p-3 bg-white border border-slate-200 text-slate-500 hover:text-brand disabled:opacity-50">
            <div className={isRefreshing ? 'animate-spin' : ''}>
              <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg>
            </div>
          </button>

          <div className="relative" ref={menuRef}>
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="flex items-center gap-3 bg-white border border-slate-200 pl-2 pr-4 py-2 hover:bg-slate-50 transition-all shadow-sm">
              <div className="w-9 h-9 bg-brand text-white flex items-center justify-center font-bold text-sm">{initials}</div>
              <div className="hidden sm:block text-left"><p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Account</p><p className="text-sm font-semibold text-slate-700 truncate max-w-[150px]">{userEmail?.split('@')[0]}</p></div>
              <Icons.ChevronDown />
            </button>
            {isMenuOpen && (
              <div className="absolute right-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl z-50 animate-in fade-in slide-in-from-top-2">
                <div className="p-4 border-b border-slate-100 bg-slate-50/50"><p className="text-xs font-bold text-slate-400 uppercase mb-1">Accesso effettuato come</p><p className="text-sm font-semibold text-slate-900 truncate">{userEmail}</p></div>
                <div className="p-2">
                  <button onClick={() => { onNavigate('ADMIN_PROFILE'); setIsMenuOpen(false); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 text-left"><Icons.User /> Profilo Aziendale</button>
                  <button onClick={() => { onNavigate('ADMIN_TAXONOMY'); setIsMenuOpen(false); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 text-left"><Icons.Briefcase /> Categorie & Contratti</button>
                  <button onClick={() => { onNavigate('ADMIN_SETTINGS'); setIsMenuOpen(false); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 text-left"><Icons.Settings /> Impostazioni SaaS</button>
                </div>
                <div className="p-2 border-t border-slate-100"><button onClick={onLogout} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-red-500 hover:bg-red-50 transition-colors font-semibold text-left"><Icons.LogOut /> Esci dal sistema</button></div>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="flex gap-4 mb-8">
        <button onClick={onCreateJob} className="flex items-center gap-2 bg-brand text-white px-8 py-4 font-bold hover:bg-brand-dark transition-all"><Icons.Plus /> Nuova Posizione</button>
        <button onClick={onViewApplications} className="flex items-center gap-2 bg-white text-slate-700 border border-slate-200 px-8 py-4 font-bold hover:bg-slate-50">
          <Icons.Users /> Visualizza Candidature ({applications.length})
        </button>
      </div>

      <StatsGrid stats={[
          { label: 'Posizioni Attive', value: stats.totalJobs, trend: 'Dashboard Live', trendColor: 'text-brand' },
          { label: 'Candidati Totali', value: stats.totalApps, trend: `+${stats.recentApps} ultimi 7gg`, trendColor: 'text-blue-600' },
          { label: 'Media Candidati', value: stats.avgAppsPerJob, trend: 'Ottimo engagement' },
          { label: 'Tasso AI', value: '100%', trend: 'Assistente attivo', trendColor: 'text-brand' }
        ]} />

      <div className="bg-white border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-8 border-b border-slate-200 bg-slate-50/50 flex justify-between items-center"><h3 className="text-xl font-bold text-slate-900">Gestione Annunci</h3><span className="text-sm font-bold text-slate-400 uppercase tracking-widest">{jobs.length} Posizioni</span></div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr><th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase">Posizione</th><th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase">Categoria</th><th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase">Candidati</th><th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase text-right">Azioni</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {jobs.map(job => (
                <tr key={job.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-8 py-6 font-bold text-slate-900 text-lg">{job.title}</td>
                  <td className="px-8 py-6"><span className="px-3 py-1.5 bg-slate-100 text-xs font-bold uppercase rounded">{job.category}</span></td>
                  <td className="px-8 py-6 text-slate-500 text-lg font-bold">{applications.filter(a => a.jobId === job.id).length}</td>
                  <td className="px-8 py-6 text-right"><div className="flex justify-end gap-3">
                    <button onClick={() => onEditJob(job)} className="text-brand p-3 hover:bg-brand-light rounded-full"><Icons.Edit /></button>
                    <button onClick={() => onRemoveJob(job.id)} className="text-red-500 p-3 hover:bg-red-50 rounded-full"><Icons.Trash /></button>
                  </div></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Job } from '../types';
import { Icons } from '../constants';
import { generateJobDescription } from '../geminiService';

interface JobFormProps {
  initialData?: Job;
  onSubmit: (job: Omit<Job, 'id' | 'postedAt'>) => void;
  onCancel: () => void;
  isAiEnabled: boolean;
  availableCategories: string[];
  availableTypes: string[];
}

export const JobForm: React.FC<JobFormProps> = ({ 
  initialData, 
  onSubmit, 
  onCancel, 
  isAiEnabled, 
  availableCategories, 
  availableTypes 
}) => {
  const [formData, setFormData] = useState({
    title: '',
    company: '',
    category: '',
    type: '',
    location: '',
    description: '',
    requirements: '',
    salaryRange: '',
    isFeatured: false
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        title: initialData.title,
        company: initialData.company,
        category: initialData.category,
        type: initialData.type,
        location: initialData.location,
        description: initialData.description,
        requirements: initialData.requirements.join(', '),
        salaryRange: initialData.salaryRange || '',
        isFeatured: initialData.isFeatured || false
      });
    } else {
      setFormData(prev => ({
        ...prev,
        category: availableCategories[0] || '',
        type: availableTypes[0] || ''
      }));
    }
  }, [initialData, availableCategories, availableTypes]);

  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiAssist = async () => {
    if (!formData.title) {
      alert("Inserisci un titolo per usare l'assistente AI");
      return;
    }
    setIsGenerating(true);
    const generated = await generateJobDescription(formData.title, formData.category, formData.requirements);
    setFormData(prev => ({ ...prev, description: generated || '' }));
    setIsGenerating(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.category || !formData.type) {
      alert("Assicurati di selezionare una categoria e un tipo di contratto.");
      return;
    }
    onSubmit({
      ...formData,
      requirements: formData.requirements.split(',').map(r => r.trim())
    });
  };

  return (
    <div className="max-w-3xl mx-auto bg-white p-8 shadow-sm border border-slate-200">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-2xl font-bold text-slate-900">{initialData ? 'Modifica Posizione' : 'Nuova Posizione Aperta'}</h2>
        <button onClick={onCancel} className="text-slate-400 hover:text-slate-600">Annulla</button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="bg-brand-light/20 border border-brand/10 p-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${formData.isFeatured ? 'bg-amber-500 text-white' : 'bg-slate-200 text-slate-500'}`}><Icons.Sparkles /></div>
            <div><p className="text-sm font-bold text-slate-900">Metti in evidenza</p></div>
          </div>
          <button type="button" onClick={() => setFormData({...formData, isFeatured: !formData.isFeatured})} className={`w-12 h-6 rounded-full transition-all relative ${formData.isFeatured ? 'bg-brand' : 'bg-slate-300'}`}>
            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${formData.isFeatured ? 'left-7' : 'left-1'}`}></div>
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Titolo del lavoro</label>
            <input required className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="es. Frontend Developer" value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Luogo</label>
            <input required className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="es. Milano / Remote" value={formData.location} onChange={e => setFormData({ ...formData, location: e.target.value })} />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Categoria</label>
            <select required className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none bg-white" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value })}>
              <option value="" disabled>Seleziona categoria</option>
              {availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Tipo Contratto</label>
            <select required className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none bg-white" value={formData.type} onChange={e => setFormData({ ...formData, type: e.target.value })}>
              <option value="" disabled>Seleziona tipo</option>
              {availableTypes.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Requisiti Chiave (separati da virgola)</label>
          <input className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="es. React, TypeScript, 3 anni esperienza" value={formData.requirements} onChange={e => setFormData({ ...formData, requirements: e.target.value })} />
        </div>

        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <label className="text-sm font-semibold text-slate-700">Descrizione del lavoro</label>
            {isAiEnabled && <button type="button" onClick={handleAiAssist} disabled={isGenerating} className="flex items-center gap-2 text-xs font-bold text-brand disabled:opacity-50"><Icons.Sparkles /> {isGenerating ? 'Generando...' : 'Aiutami con AI'}</button>}
          </div>
          <textarea required rows={10} className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="Scrivi qui la descrizione..." value={formData.description} onChange={e => setFormData({ ...formData, description: e.target.value })}></textarea>
        </div>

        <div className="flex justify-end gap-4 pt-4">
          <button type="button" onClick={onCancel} className="px-6 py-2 font-medium text-slate-600 hover:bg-slate-50">Annulla</button>
          <button type="submit" className="px-6 py-2 font-bold bg-brand text-white hover:bg-brand-dark transition-colors">{initialData ? 'Salva Modifiche' : 'Pubblica Annuncio'}</button>
        </div>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { Icons } from '../constants';
import { supabase } from '../supabaseClient';

interface TaxonomyManagerProps {
  onBack: () => void;
  categories: string[];
  jobTypes: string[];
  onRefresh: () => void;
}

export const TaxonomyManager: React.FC<TaxonomyManagerProps> = ({ onBack, categories, jobTypes, onRefresh }) => {
  const [newCategory, setNewCategory] = useState('');
  const [newJobType, setNewJobType] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCategory.trim()) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('job_categories').insert([{ name: newCategory.trim() }]);
      if (error) throw error;
      setNewCategory('');
      onRefresh();
    } catch (err: any) {
      alert("Errore nell'aggiunta: " + (err.message || "Forse il nome esiste già?"));
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDeleteCategory = async (name: string) => {
    if (!confirm(`Sei sicuro di voler eliminare la categoria "${name}"? Gli annunci esistenti potrebbero non essere più filtrabili correttamente.`)) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('job_categories').delete().eq('name', name);
      if (error) throw error;
      onRefresh();
    } catch (err) {
      alert("Errore durante l'eliminazione.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddJobType = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newJobType.trim()) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('job_types').insert([{ name: newJobType.trim() }]);
      if (error) throw error;
      setNewJobType('');
      onRefresh();
    } catch (err: any) {
      alert("Errore nell'aggiunta: " + (err.message || "Forse il nome esiste già?"));
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDeleteJobType = async (name: string) => {
    if (!confirm(`Sei sicuro di voler eliminare il tipo di contratto "${name}"?`)) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('job_types').delete().eq('name', name);
      if (error) throw error;
      onRefresh();
    } catch (err) {
      alert("Errore durante l'eliminazione.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="w-full px-6 lg:px-12 py-20 animate-in fade-in duration-500">
      <button onClick={onBack} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 mb-8 font-medium group">
        <span className="group-hover:-translate-x-1 transition-transform"><Icons.ChevronLeft /></span> Torna alla Dashboard
      </button>

      <div className="flex flex-col lg:flex-row gap-12">
        {/* Gestione Categorie */}
        <div className="flex-1 space-y-8">
          <div className="bg-white border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-8 border-b border-slate-100 bg-slate-50/50">
              <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-3">
                <Icons.Briefcase />
                Gestione Categorie
              </h2>
              <p className="text-sm text-slate-500">Aggiungi o rimuovi i settori per i tuoi annunci.</p>
            </div>
            <div className="p-8">
              <form onSubmit={handleAddCategory} className="flex gap-2 mb-8">
                <input
                  required
                  className="flex-1 px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none"
                  placeholder="Nuova categoria (es. Logistica)"
                  value={newCategory}
                  onChange={e => setNewCategory(e.target.value)}
                  disabled={isProcessing}
                />
                <button 
                  type="submit"
                  disabled={isProcessing}
                  className="bg-brand text-white px-6 py-3 font-bold hover:bg-brand-dark transition-all shadow-md shadow-brand/10 disabled:opacity-50"
                >
                  Aggiungi
                </button>
              </form>

              <div className="space-y-2">
                {categories.length > 0 ? categories.map(cat => (
                  <div key={cat} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 group">
                    <span className="font-semibold text-slate-700">{cat}</span>
                    <button 
                      onClick={() => handleDeleteCategory(cat)}
                      disabled={isProcessing}
                      className="text-slate-400 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                    >
                      <Icons.Trash />
                    </button>
                  </div>
                )) : <p className="text-slate-400 italic text-center py-4">Nessuna categoria configurata.</p>}
              </div>
            </div>
          </div>
        </div>

        {/* Gestione Tipi Contratto */}
        <div className="flex-1 space-y-8">
          <div className="bg-white border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-8 border-b border-slate-100 bg-slate-50/50">
              <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-3">
                <Icons.Clock />
                Tipi di Contratto
              </h2>
              <p className="text-sm text-slate-500">Gestisci le modalità contrattuali offerte.</p>
            </div>
            <div className="p-8">
              <form onSubmit={handleAddJobType} className="flex gap-2 mb-8">
                <input
                  required
                  className="flex-1 px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none"
                  placeholder="Nuovo tipo (es. Apprendistato)"
                  value={newJobType}
                  onChange={e => setNewJobType(e.target.value)}
                  disabled={isProcessing}
                />
                <button 
                  type="submit"
                  disabled={isProcessing}
                  className="bg-brand text-white px-6 py-3 font-bold hover:bg-brand-dark transition-all shadow-md shadow-brand/10 disabled:opacity-50"
                >
                  Aggiungi
                </button>
              </form>

              <div className="space-y-2">
                {jobTypes.length > 0 ? jobTypes.map(type => (
                  <div key={type} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 group">
                    <span className="font-semibold text-slate-700">{type}</span>
                    <button 
                      onClick={() => handleDeleteJobType(type)}
                      disabled={isProcessing}
                      className="text-slate-400 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                    >
                      <Icons.Trash />
                    </button>
                  </div>
                )) : <p className="text-slate-400 italic text-center py-4">Nessun tipo contratto configurato.</p>}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
